USE campus_parking;

-- 0. Make sure the maintenance column exists (no-op if it already does).
SET @has := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'parking_slots' AND COLUMN_NAME = 'out_of_service');
SET @ddl := IF(@has = 0, 'ALTER TABLE parking_slots ADD COLUMN out_of_service BOOLEAN NOT NULL DEFAULT FALSE', 'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 1. Remove any earlier demo data.
DELETE FROM parking_records WHERE vehicle_id IN (SELECT vehicle_id FROM vehicles WHERE owner_contact = 'DEMO');
DELETE FROM vehicles WHERE owner_contact = 'DEMO';
UPDATE parking_slots SET is_occupied = FALSE WHERE slot_id NOT IN (SELECT slot_id FROM parking_records WHERE exit_time IS NULL);

